UPDATE passenger_ai_conversation
SET last_message_sequence = #{sequence},
    active_request_no = #{requestNo},
    active_request_started_at = #{startedAt},
    last_message_at = #{lastMessageAt},
    row_version = row_version + 1,
    updated_at = #{lastMessageAt}
WHERE id = #{id}
  AND row_version = #{expectedRowVersion}

UPDATE passenger_ai_conversation
SET active_request_no = NULL,
    active_request_started_at = NULL,
    last_message_sequence = #{sequence},
    last_message_at = #{lastMessageAt},
    row_version = row_version + 1,
    updated_at = #{lastMessageAt}
WHERE id = #{id}
  AND active_request_no = #{requestNo}

