    row_version = row_version + 1,
    updated_at = #{lastMessageAt}
WHERE id = #{id}
  AND row_version = #{expectedRowVersion}

mapper.select:
SELECT c.id, c.conversation_no, c.customer_id, c.create_idempotency_key, c.scene_code, COALESCE(NULLIF(c.title, ''), (SELECT m.content FROM passenger_ai_message m WHERE m.conversation_id = c.id AND m.role = 'USER' ORDER BY m.sequence_no ASC LIMIT 1), '新对话') AS title, c.status, c.last_message_sequence, c.memory_summary, c.summary_through_sequence, c.row_version, c.active_request_no, c.active_request_started_at, c.last_message_at, c.delete_reason, c.delete_operation_no, c.deleted_at, c.created_at, c.updated_at FROM passenger_ai_conversation c WHERE c.customer_id = #{customerId} AND c.status = 'ACTIVE' AND c.deleted_at IS NULL
AND (c.last_message_at < #{beforeLastMessageAt} OR (c.last_message_at = #{beforeLastMessageAt} AND c.id < #{beforeId}))
ORDER BY c.last_message_at DESC, c.id DESC LIMIT #{limit}
